function resolveTenant(auth: JwtPayload): string {
  const tenantId = auth['custom:tenant_id'];
  if (!tenantId) throw new UnauthorizedError('Missing tenant claim');
  return tenantId;
}

const breakers = new Map<string, CircuitBreaker>();

function getBreaker(tenantId: string) {
  if (!breakers.has(tenantId)) {
    breakers.set(tenantId, new CircuitBreaker(callWebhook, { timeout: 3000 }));
  }
  return breakers.get(tenantId)!;
}
